export const AUTH_PROVIDER_CONTENT =
  '// @internal — No changes needed\n\nimport React, { useState } from "react";\nimport { CookieAuthGuard } from "./cookie-auth/CookieAuthGuard";\nimport { JwtAuthGuard } from "./jwt-auth/JwtAuthGuard";\nimport { setActiveStrategy } from "./manager";\nimport { type AuthStrategy } from "./manager";\n\ninterface AuthProviderProps {\n  strategy: AuthStrategy;\n  children: React.ReactNode;\n}\n\n/**\n * Global AuthProvider that wraps the application and conditionally renders\n * the appropriate AuthGuard based on the configured strategy.\n * It also configures the global API client to use the correct TokenProvider.\n */\nexport const AuthProvider = ({ strategy, children }: AuthProviderProps) => {\n  // Synchronously configure the API client\'s Strategy on the first render\n  useState(() => {\n    setActiveStrategy(strategy);\n    return true;\n  });\n\n  switch (strategy) {\n    case "cookie":\n      return <CookieAuthGuard>{children}</CookieAuthGuard>;\n    case "jwt":\n      return <JwtAuthGuard>{children}</JwtAuthGuard>;\n    default:\n      console.warn(\n        `Unknown auth strategy: ${strategy}. Falling back to jwt.`,\n      );\n      return <JwtAuthGuard>{children}</JwtAuthGuard>;\n  }\n};\n';

export const AUTH_MANAGER_CONTENT =
  '// @internal — No changes needed\r\n\r\nimport { type TokenProvider } from "./types";\r\nimport { cookieTokenProvider } from "./cookie-auth/provider";\r\nimport { jwtTokenProvider } from "./jwt-auth/provider";\r\n\r\nexport type AuthStrategy = "jwt" | "cookie";\r\n\r\nlet activeTokenProvider: TokenProvider = jwtTokenProvider;\r\n\r\n/**\r\n * Updates the globally active token provider based on the chosen strategy.\r\n * Used internally by the <AuthProvider> component.\r\n */\r\nexport const setActiveStrategy = (strategy: AuthStrategy) => {\r\n  switch (strategy) {\r\n    case "cookie":\r\n      activeTokenProvider = cookieTokenProvider;\r\n      break;\r\n    case "jwt":\r\n      activeTokenProvider = jwtTokenProvider;\r\n      break;\r\n  }\r\n};\r\n\r\n/**\r\n * Proxy provider that dynamically resolves to the currently active token provider.\r\n * This ensures the API client always uses the correctly configured strategy without\r\n * needing to recreate the Axios instance.\r\n */\r\nexport const proxyTokenProvider: TokenProvider = {\r\n  getToken: () => activeTokenProvider.getToken(),\r\n  get refreshToken() {\r\n    return activeTokenProvider.refreshToken;\r\n  },\r\n  get setTokens() {\r\n    return activeTokenProvider.setTokens;\r\n  },\r\n  get setSession() {\r\n    return activeTokenProvider.setSession;\r\n  },\r\n  get clearTokens() {\r\n    return activeTokenProvider.clearTokens;\r\n  },\r\n  get getCustomHeaders() {\r\n    return activeTokenProvider.getCustomHeaders;\r\n  },\r\n  get setCustomHeaders() {\r\n    return activeTokenProvider.setCustomHeaders;\r\n  },\r\n  get removeCustomHeader() {\r\n    return activeTokenProvider.removeCustomHeader;\r\n  },\r\n};\r\n\r\n/**\r\n * Use this function to access the active token provider from an external file.\r\n * This is the recommended way to get or set auth tokens after login.\r\n */\r\nexport function getActiveProvider(): TokenProvider | null {\r\n  return activeTokenProvider ?? null;\r\n}\r\n';

export const AUTH_TYPES_CONTENT =
  "/** Standardized API error response */\r\nexport interface ApiError {\r\n  message: string;\r\n  code?: string;\r\n  statusCode?: number;\r\n  originalError?: unknown;\r\n}\r\n\r\n/** Pluggable authentication strategy */\r\nexport interface TokenProvider {\r\n  /** Get current access token */\r\n  getToken: () => Promise<string | null> | string | null;\r\n\r\n  /** Refresh expired token */\r\n  refreshToken?: () => Promise<string | null>;\r\n\r\n  /** Return custom headers to inject into all requests */\r\n  getCustomHeaders?: () =>\r\n    | Promise<Record<string, string>>\r\n    | Record<string, string>;\r\n\r\n  /** Replace custom headers for all future requests */\r\n  setCustomHeaders?: (headers: Record<string, string>) => void;\r\n\r\n  /** Remove a specific custom header */\r\n  removeCustomHeader?: (key: string) => void;\r\n\r\n  /** Set new auth tokens (called on login/signup for token-based auth) */\r\n  setTokens?: (tokens: { accessToken: string; refreshToken?: string }) => void;\r\n\r\n  /** Activate or set session on login (handles tokens, cookie-based sessions, and optional headers) */\r\n  setSession?: (\r\n    tokens?: { accessToken?: string; refreshToken?: string },\r\n    headers?: Record<string, string>,\r\n  ) => void;\r\n\r\n  /** Clear all auth tokens (called on logout) */\r\n  clearTokens?: () => void;\r\n}\r\n";

export const REEX_CONFIG_CONTENT =
  "// @internal — No changes needed\n/* eslint-disable @typescript-eslint/no-explicit-any */\n\n/**\n * Enforces the basic structure of Reex definition files.\n * Use with the `satisfies` operator for maximum IntelliSense:\n * export const myApi = { ... } satisfies ReexDefinition;\n */\nexport type ReexDefinition = Record<string, (...args: unknown[]) => Promise<unknown>>;\n\n/**\n * Enforces the structure of the Reex configuration file (api.config.ts).\n * Use with the `satisfies` operator for maximum IntelliSense.\n */\nexport interface ReexConfig {\n  baseURL: string;\n  unwrapResponseData: boolean;\n  enableApiLogging: boolean;\n  auth: {\n    loginRoute?: string;\n    refreshEndpoint: string;\n    accessTokenKey: string;\n    refreshTokenKey: string;\n    extractTokens: (responseBody: unknown) => { accessToken?: string; refreshToken?: string };\n    refreshWithCookie: () => Promise<import(\"axios\").AxiosResponse<unknown>>;\n    refreshWithToken: (storedRefreshToken: string) => Promise<import(\"axios\").AxiosResponse<unknown>>;\n  };\n}\n";

