export const API_CONFIG_CONTENT =
  "// @user-config — Update routes, keys, and endpoints to match your backend.\n\nimport axios from \"axios\";\nimport { type ReexConfig } from \"./.reex/config\";\n\n// Replace this with your API base URL or an environment variable\n// (e.g. process.env.NEXT_PUBLIC_API_URL).\nconst BASE_URL = \"https://example.com/api/v1\";\n\nexport const apiConfig: ReexConfig = {\n  baseURL: BASE_URL,\n\n  // Set to `true` if your API wraps every response in a top-level `data` property.\n  // When enabled, also turn on \"Unwrap Response Data\" in the Reex UI before\n  // saving or copying generated response interfaces.\n  unwrapResponseData: false,\n\n  // Enable request/response logging.\n  // For development only, consider:\n  //   process.env.NODE_ENV === \"development\"\n  // or\n  //   import.meta.env.DEV\n  enableApiLogging: false,\n\n  auth: {\n    // ---------------------------------------------------------------------------\n    // General authentication configuration\n    // ---------------------------------------------------------------------------\n\n    // The route users will be redirected to when logged out.\n    // If left undefined, it defaults to the application root (window.origin).\n    loginRoute: \"/login\",\n\n    // Refresh token endpoint. Update this to match your backend.\n    refreshEndpoint: `${BASE_URL}/auth/refresh`,\n\n    // ---------------------------------------------------------------------------\n    // JWT / Bearer token authentication\n    // Use these options when the `ReexProvider` auth strategy is `\"jwt\"`.\n    // ---------------------------------------------------------------------------\n\n    // Send the refresh token to your backend to obtain a new access token.\n    // Rename `refreshToken` in the request body if your backend expects\n    // a different field name (e.g. `refresh_token`).\n    refreshWithToken: async (storedRefreshToken: string) =>\n      axios.post(apiConfig.auth.refreshEndpoint, {\n        refreshToken: storedRefreshToken,\n      }),\n\n    // Extract authentication tokens from your backend response.\n    //\n    // Note: `responseBody` is affected by the `unwrapResponseData` setting.\n    // - When `unwrapResponseData` is `true`, `responseBody` contains the\n    //   unwrapped `data` object.\n    // - When `unwrapResponseData` is `false`, `responseBody` contains the\n    //   full response body.\n    //\n    // Update these paths to match your API response structure.\n    extractTokens: (responseBody: Record<string, unknown>) => ({\n      accessToken: responseBody?.accessToken as string | undefined,\n      refreshToken: responseBody?.refreshToken as string | undefined,\n    }),\n\n    // Storage key names for authentication tokens.\n    // Change these if you prefer different key names.\n    //\n    // Note: The access token is stored in memory by default.\n    // It is only persisted to localStorage if your backend does not\n    // return a refresh token.\n    accessTokenKey: \"access_token\",\n    refreshTokenKey: \"refresh_token\",\n\n    // ---------------------------------------------------------------------------\n    // Cookie-based authentication\n    // Use this when the `ReexProvider` auth strategy is `\"cookie\"`.\n    // ---------------------------------------------------------------------------\n\n    // Request a new access token using HttpOnly cookies.\n    refreshWithCookie: async () =>\n      axios.post(apiConfig.auth.refreshEndpoint, undefined, {\n        withCredentials: true,\n\n        // Add any headers required by your backend when refreshing tokens.\n        // headers: { \"X-Client-ID\": \"1234\" },\n      }),\n  },\n};\n";

export const COOKIE_GUARD_CONTENT =
  '// @internal — No changes needed\n"use client";\n\nimport { useEffect, useState } from "react";\nimport { cookieTokenProvider } from "./provider";\nimport { apiClient } from "../../core";\nimport LoadingScreen from "../../custom/loadingScreen/LoadingScreen";\n\n/**\n * Restores the user session on mount via the refresh endpoint.\n */\n\nexport const CookieAuthGuard = ({\n  children,\n}: {\n  children: React.ReactNode;\n}) => {\n  // Configure API client synchronously on mount\n  useState(() => {\n    apiClient.defaults.withCredentials = true;\n    return true;\n  });\n\n  const [isReady, setIsReady] = useState(false);\n\n  useEffect(() => {\n    // Attempt to restore access token from refresh cookie or localStorage\n    const initAuth = async () => {\n      try {\n        await cookieTokenProvider.refreshToken?.();\n      } catch (error) {\n        console.warn("Auth initialization failed:", error);\n      } finally {\n        setIsReady(true);\n      }\n    };\n\n    initAuth();\n  }, []);\n\n  // Listen for auth:logout events dispatched by core.ts when token refresh fails\n  useEffect(() => {\n    const handleLogout = () => {\n      cookieTokenProvider.clearTokens();\n      setIsReady(true); // Keep app rendered (in unauthenticated state)\n    };\n\n    window.addEventListener("auth:logout", handleLogout);\n    return () => window.removeEventListener("auth:logout", handleLogout);\n  }, []);\n\n  // Replace with your app\'s loading component\n  if (!isReady) {\n    return <LoadingScreen />;\n  }\n\n  return <>{children}</>;\n};\n';

export const COOKIE_PROVIDER_CONTENT =
  "// @internal — No changes needed\r\nimport { type TokenProvider } from \"../types\";\r\nimport { apiConfig } from \"../../api.config\";\r\n\r\nlet isCookieAuthActive: boolean = false;\r\nlet customHeaders: Record<string, string> | null = null;\r\nlet refreshPromise: Promise<string | null> | null = null;\r\n\r\n// Used to track auth status across tabs, without exposing the actual token to JS\r\nconst COOKIE_FLAG_KEY = \"reex_is_cookie_auth_active\";\r\n\r\ninterface CookieTokenProvider extends TokenProvider {\r\n  setSession: (\r\n    tokens?: { accessToken?: string; refreshToken?: string },\r\n    headers?: Record<string, string>,\r\n  ) => void;\r\n  clearTokens: () => void;\r\n  setCustomHeaders: (headers: Record<string, string>) => void;\r\n  getCustomHeaders: () => Record<string, string>;\r\n  removeCustomHeader: (key: string) => void;\r\n}\r\n\r\n/**\r\n * Cookie-Only Token Provider\r\n * - Access Token: Managed securely by the browser via HttpOnly cookies\r\n * - Refresh Mechanism: Automatic via HttpOnly cookies\r\n * - Frontend State: Maintained via a simple boolean flag\r\n */\r\nexport const cookieTokenProvider: CookieTokenProvider = {\r\n  getToken: () => {\r\n    // Return a proxy value so `useIsAuthenticated` knows we are logged in.\r\n    // The actual token is sent automatically by the browser via cookies.\r\n    if (isCookieAuthActive) return \"cookie-active\";\r\n    if (typeof window !== \"undefined\") {\r\n      return localStorage.getItem(COOKIE_FLAG_KEY) === \"true\" ? \"cookie-active\" : null;\r\n    }\r\n    return null;\r\n  },\r\n\r\n  getCustomHeaders: () => {\r\n    if (customHeaders) return customHeaders;\r\n    if (typeof window !== \"undefined\") {\r\n      const stored = localStorage.getItem(\"reex_custom_headers\");\r\n      if (stored) {\r\n        try {\r\n          return JSON.parse(stored);\r\n        } catch {\r\n          return {};\r\n        }\r\n      }\r\n    }\r\n    return {};\r\n  },\r\n\r\n  setCustomHeaders: (headers) => {\r\n    customHeaders = headers;\r\n    if (typeof window !== \"undefined\") {\r\n      localStorage.setItem(\"reex_custom_headers\", JSON.stringify(headers));\r\n    }\r\n  },\r\n\r\n  removeCustomHeader: (key) => {\r\n    if (customHeaders) {\r\n      delete customHeaders[key];\r\n    }\r\n    if (typeof window !== \"undefined\") {\r\n      const stored = localStorage.getItem(\"reex_custom_headers\");\r\n      if (stored) {\r\n        try {\r\n          const headers = JSON.parse(stored);\r\n          delete headers[key];\r\n          localStorage.setItem(\"reex_custom_headers\", JSON.stringify(headers));\r\n        } catch {\r\n          // ignore JSON parse / storage errors\r\n        }\r\n      }\r\n    }\r\n  },\r\n\r\n  setSession: (_tokens, headers) => {\r\n    // The actual token is set by the backend via Set-Cookie headers.\r\n    // We just set a primitive flag so the frontend knows the user is logged in.\r\n    isCookieAuthActive = true;\r\n    if (headers) {\r\n      cookieTokenProvider.setCustomHeaders(headers);\r\n    }\r\n    if (typeof window !== \"undefined\") {\r\n      localStorage.setItem(COOKIE_FLAG_KEY, \"true\");\r\n      window.dispatchEvent(new Event(\"auth:login\"));\r\n    }\r\n  },\r\n\r\n  clearTokens: () => {\r\n    isCookieAuthActive = false;\r\n    customHeaders = null;\r\n    refreshPromise = null;\r\n    if (typeof window !== \"undefined\") {\r\n      localStorage.removeItem(COOKIE_FLAG_KEY);\r\n      localStorage.removeItem(\"reex_custom_headers\");\r\n    }\r\n  },\r\n\r\n  refreshToken: async () => {\r\n    if (refreshPromise) {\r\n      return refreshPromise;\r\n    }\r\n\r\n    refreshPromise = (async () => {\r\n      try {\r\n        await apiConfig.auth.refreshWithCookie();\r\n\r\n        // If the refresh succeeds, the browser now has the updated cookie.\r\n        isCookieAuthActive = true;\r\n        if (typeof window !== \"undefined\") {\r\n          localStorage.setItem(COOKIE_FLAG_KEY, \"true\");\r\n          window.dispatchEvent(new Event(\"auth:login\"));\r\n        }\r\n\r\n        return \"cookie-active\";\r\n      } catch {\r\n        // Refresh failed, clear the session flag\r\n        isCookieAuthActive = false;\r\n        if (typeof window !== \"undefined\") {\r\n          localStorage.removeItem(COOKIE_FLAG_KEY);\r\n        }\r\n        return null;\r\n      } finally {\r\n        refreshPromise = null;\r\n      }\r\n    })();\r\n\r\n    return refreshPromise;\r\n  },\r\n};\r\n";

export const JWT_GUARD_CONTENT =
  '// @internal — No changes needed\r\n"use client";\r\n\r\nimport { useEffect, useState } from "react";\r\nimport { jwtTokenProvider } from "./provider";\r\nimport { apiConfig } from "../../api.config";\r\nimport LoadingScreen from "../../custom/loadingScreen/LoadingScreen";\r\n\r\n/**\r\n * Restores the user session on mount by exchanging the stored refresh token.\r\n * Wrap your root layout with `<JwtAuthGuard>`. Configure in `api.config.ts`.\r\n */\r\n\r\nexport const JwtAuthGuard = ({\r\n  children,\r\n}: {\r\n  children: React.ReactNode;\r\n}) => {\r\n  const [isReady, setIsReady] = useState(false);\r\n\r\n  useEffect(() => {\r\n    // Attempt to restore session from stored tokens\r\n    const initAuth = async () => {\r\n      const hasRefreshToken = !!localStorage.getItem(\r\n        apiConfig.auth.refreshTokenKey,\r\n      );\r\n      const hasAccessToken = !!localStorage.getItem(apiConfig.auth.accessTokenKey);\r\n\r\n      if (hasRefreshToken && jwtTokenProvider?.refreshToken) {\r\n        try {\r\n          await jwtTokenProvider.refreshToken();\r\n        } catch (error) {\r\n          console.warn("Session restoration failed:", error);\r\n        }\r\n      } else if (hasAccessToken && jwtTokenProvider?.refreshToken) {\r\n        // Access-token-only fallback: let the provider restore from storage\r\n        await jwtTokenProvider.refreshToken();\r\n      }\r\n\r\n      setIsReady(true);\r\n    };\r\n\r\n    initAuth();\r\n  }, []);\r\n\r\n  // Listen for auth:logout events dispatched by core.ts when token refresh fails\r\n  useEffect(() => {\r\n    const handleLogout = () => {\r\n      jwtTokenProvider.clearTokens();\r\n      setIsReady(true); // Keep app rendered (in unauthenticated state)\r\n    };\r\n\r\n    window.addEventListener("auth:logout", handleLogout);\r\n    return () => window.removeEventListener("auth:logout", handleLogout);\r\n  }, []);\r\n\r\n  // Replace with your app\'s loading component\r\n  if (!isReady) return <LoadingScreen />;\r\n\r\n  return <>{children}</>;\r\n};\r\n';

export const JWT_PROVIDER_CONTENT =
  "// @internal — No changes needed\nimport { apiConfig } from \"../../api.config\";\nimport { type TokenProvider } from \"../types\";\n\n\n/**\n * JWT Token Provider\n * - Access Token & Refresh Token: Persisted in localStorage\n *\n * Edit `api.config.ts` to customize routes and storage keys, and refresh payload.\n */\n\nlet accessToken: string | null = null;\nlet customHeaders: Record<string, string> | null = null;\nlet refreshPromise: Promise<string | null> | null = null;\n\n/**\n * Decodes the JWT `exp` claim and checks whether it has passed.\n * No library needed — JWT payloads are plain base64url-encoded JSON.\n * Returns false for non-JWT strings so opaque tokens are never blocked.\n */\nconst isTokenExpired = (token: string): boolean => {\n  try {\n    const payload = JSON.parse(atob(token.split(\".\")[1]));\n    return typeof payload.exp === \"number\" && payload.exp * 1000 < Date.now();\n  } catch {\n    return false;\n  }\n};\n\ninterface JwtTokenProvider extends TokenProvider {\n  setTokens: (tokens: { accessToken: string; refreshToken?: string }) => void;\n  setSession: (\n    tokens?: { accessToken?: string; refreshToken?: string },\n    headers?: Record<string, string>,\n  ) => void;\n  clearTokens: () => void;\n  setCustomHeaders: (headers: Record<string, string>) => void;\n  getCustomHeaders: () => Record<string, string>;\n  removeCustomHeader: (key: string) => void;\n}\n\nexport const jwtTokenProvider: JwtTokenProvider = {\n  getToken: () => {\n    const token = accessToken ?? (\n      typeof window !== \"undefined\"\n        ? localStorage.getItem(apiConfig.auth.accessTokenKey)\n        : null\n    );\n\n    if (token) {\n      if (isTokenExpired(token)) {\n        accessToken = null;\n        if (typeof window !== \"undefined\") {\n          localStorage.removeItem(apiConfig.auth.accessTokenKey);\n          const hasRefreshToken = !!localStorage.getItem(apiConfig.auth.refreshTokenKey);\n          if (!hasRefreshToken) {\n            window.dispatchEvent(new Event(\"auth:logout\"));\n            return null;\n          }\n        }\n      } else {\n        return token;\n      }\n    }\n\n    if (typeof window !== \"undefined\") {\n      const storedRefreshToken = localStorage.getItem(apiConfig.auth.refreshTokenKey);\n      if (storedRefreshToken && jwtTokenProvider.refreshToken) {\n        return jwtTokenProvider.refreshToken();\n      }\n    }\n\n    return null;\n  },\n\n  getCustomHeaders: () => {\n    if (customHeaders) return customHeaders;\n    if (typeof window !== \"undefined\") {\n      const stored = localStorage.getItem(\"reex_custom_headers\");\n      if (stored) {\n        try {\n          return JSON.parse(stored);\n        } catch {\n          return {};\n        }\n      }\n    }\n    return {};\n  },\n\n  setCustomHeaders: (headers) => {\n    customHeaders = headers;\n    if (typeof window !== \"undefined\") {\n      localStorage.setItem(\"reex_custom_headers\", JSON.stringify(headers));\n    }\n  },\n\n  removeCustomHeader: (key) => {\n    if (customHeaders) {\n      delete customHeaders[key];\n    }\n    if (typeof window !== \"undefined\") {\n      const stored = localStorage.getItem(\"reex_custom_headers\");\n      if (stored) {\n        try {\n          const headers = JSON.parse(stored);\n          delete headers[key];\n          localStorage.setItem(\"reex_custom_headers\", JSON.stringify(headers));\n        } catch {\n          // ignore JSON parse / storage errors\n        }\n      }\n    }\n  },\n\n  // Called on login/signup success with raw tokens\n  setTokens: (tokens) => {\n    const newAccessToken = tokens.accessToken;\n    const refreshToken = tokens.refreshToken;\n    accessToken = newAccessToken;\n    if (typeof window !== \"undefined\") {\n      if (refreshToken) {\n        localStorage.setItem(apiConfig.auth.refreshTokenKey, refreshToken);\n        localStorage.removeItem(apiConfig.auth.accessTokenKey);\n      } else if (newAccessToken) {\n        localStorage.setItem(apiConfig.auth.accessTokenKey, newAccessToken);\n        localStorage.removeItem(apiConfig.auth.refreshTokenKey);\n      }\n      window.dispatchEvent(new Event(\"auth:login\"));\n    }\n  },\n\n  // Called on login with tokens and optional custom headers\n  setSession: (tokens, headers) => {\n    if (tokens?.accessToken) {\n      jwtTokenProvider.setTokens(tokens as { accessToken: string; refreshToken?: string });\n    }\n    if (headers) {\n      jwtTokenProvider.setCustomHeaders(headers);\n    }\n    if (typeof window !== \"undefined\" && !tokens?.accessToken) {\n      window.dispatchEvent(new Event(\"auth:login\"));\n    }\n  },\n\n  // Called on logout\n  clearTokens: () => {\n    accessToken = null;\n    customHeaders = null;\n    refreshPromise = null;\n    if (typeof window !== \"undefined\") {\n      localStorage.removeItem(apiConfig.auth.refreshTokenKey);\n      localStorage.removeItem(apiConfig.auth.accessTokenKey);\n      localStorage.removeItem(\"reex_custom_headers\");\n    }\n  },\n\n  // Exchange refresh token for a new access token\n  refreshToken: async () => {\n    // If a refresh is already in progress, await the existing promise instead of making a new request\n    if (refreshPromise) {\n      return refreshPromise;\n    }\n\n    refreshPromise = (async () => {\n      try {\n        if (typeof window === \"undefined\") return null;\n\n        const storedRefreshToken = localStorage.getItem(\n          apiConfig.auth.refreshTokenKey,\n        );\n\n        // Fallback: use stored access token if no refresh token\n        if (!storedRefreshToken) {\n          const storedAccessToken = localStorage.getItem(\n            apiConfig.auth.accessTokenKey,\n          );\n          if (storedAccessToken) {\n            accessToken = storedAccessToken;\n            return accessToken;\n          }\n          throw new Error(\"No refresh token found\");\n        }\n\n        const response = await apiConfig.auth.refreshWithToken(storedRefreshToken);\n\n        const isRawAxiosResponse =\n          response?.config && response?.headers && response?.status;\n\n        const unwrappedData = isRawAxiosResponse ? response.data : response;\n        const responseData = apiConfig.unwrapResponseData ? (unwrappedData?.data ?? unwrappedData) : unwrappedData;\n\n        const extracted = apiConfig.auth.extractTokens(responseData);\n\n        if (!extracted?.accessToken && !extracted?.refreshToken) {\n          console.error(\n            \"\\n[Reex Auth Error] 🛑 Token extraction failed during refresh.\\n\" +\n            \"Both 'accessToken' and 'refreshToken' are empty.\\n\" +\n            \"Please update the `extractTokens` function in your `api.config.ts` so it correctly maps to your backend's response structure.\\n\"\n          );\n        }\n\n        const { accessToken: newAccess = null, refreshToken: newRefresh } = extracted || {};\n        accessToken = newAccess;\n\n        if (newRefresh) {\n          localStorage.setItem(apiConfig.auth.refreshTokenKey, newRefresh);\n        }\n\n        if (newAccess && typeof window !== \"undefined\") {\n          window.dispatchEvent(new Event(\"auth:login\"));\n        }\n\n        return accessToken;\n      } catch {\n        console.warn(\"Refresh failed, logging out...\");\n        accessToken = null;\n        localStorage.removeItem(apiConfig.auth.refreshTokenKey);\n        localStorage.removeItem(apiConfig.auth.accessTokenKey);\n        return null;\n      } finally {\n        refreshPromise = null;\n      }\n    })();\n\n    return refreshPromise;\n  },\n};\n";

export const USE_AUTH_SESSION_HOOK_CONTENT =
  "// @internal — No changes needed\nimport { useCallback, useEffect, useState } from \"react\";\nimport { useQueryClient } from \"@tanstack/react-query\";\nimport { getActiveProvider } from \"../auth-methods/manager\";\nimport { apiConfig } from \"../api.config\";\n\nexport type AuthStatus = \"loading\" | \"authenticated\" | \"unauthenticated\";\n\n/**\n * Hook to manage authentication state, active sessions, and logout teardown.\n *\n * @example\n * const { status, isAuthenticated, setSession, clearSession } = useAuthSession();\n * if (status === \"loading\") return <Loading />;\n * if (!isAuthenticated) return <Login />;\n */\nexport const useAuthSession = () => {\n  const provider = getActiveProvider();\n  const queryClient = useQueryClient();\n\n  const [status, setStatus] = useState<AuthStatus>(\"loading\");\n\n  useEffect(() => {\n    const checkAuth = async () => {\n      try {\n        const token = await provider?.getToken?.();\n        setStatus(token ? \"authenticated\" : \"unauthenticated\");\n      } catch {\n        setStatus(\"unauthenticated\");\n      }\n    };\n\n    checkAuth();\n\n    // Listen to dispatch events to update UI instantly without refresh\n    const handleLogin = () => setStatus(\"authenticated\");\n    const handleLogout = () => {\n      provider?.clearTokens?.();\n      queryClient.cancelQueries();\n      queryClient.clear();\n      setStatus(\"unauthenticated\");\n\n      if (typeof window !== \"undefined\") {\n        const route = apiConfig.auth?.loginRoute || window.origin;\n        window.location.href = route;\n      }\n    };\n\n    if (typeof window !== \"undefined\") {\n      window.addEventListener(\"auth:login\", handleLogin);\n      window.addEventListener(\"auth:logout\", handleLogout);\n    }\n\n    return () => {\n      if (typeof window !== \"undefined\") {\n        window.removeEventListener(\"auth:login\", handleLogin);\n        window.removeEventListener(\"auth:logout\", handleLogout);\n      }\n    };\n  }, [provider, queryClient]);\n\n  const getToken = useCallback(\n    () => provider?.getToken?.() ?? null,\n    [provider],\n  );\n\n  const setSession = useCallback(\n    (\n      tokens?: { accessToken?: string; refreshToken?: string },\n      headers?: Record<string, string>,\n    ) => {\n      if (provider?.setSession) {\n        provider.setSession(tokens, headers);\n      } else if (tokens?.accessToken && provider?.setTokens) {\n        provider.setTokens(tokens as { accessToken: string; refreshToken?: string });\n        if (headers && provider?.setCustomHeaders) {\n          provider.setCustomHeaders(headers);\n        }\n      }\n      setStatus(\"authenticated\");\n    },\n    [provider],\n  );\n\n  const clearSession = useCallback(async () => {\n    provider?.clearTokens?.();\n\n    // Clear React Query cache\n    await queryClient.cancelQueries();\n    queryClient.clear();\n\n    setStatus(\"unauthenticated\");\n\n    if (typeof window !== \"undefined\") {\n      window.dispatchEvent(new Event(\"auth:logout\"));\n      const route = apiConfig.auth?.loginRoute || window.origin;\n      window.location.href = route;\n    }\n  }, [provider, queryClient]);\n\n  return {\n    status,\n    isAuthenticated: status === \"authenticated\",\n    isLoading: status === \"loading\",\n    getToken,\n    setSession,\n    clearSession,\n  };\n};\n";

export const NOTIFICATION_CONTENT =
  "\"use client\";\n\nimport { createContext } from \"react\";\n\nexport type NotificationType = \"success\" | \"error\" | \"warning\" | \"info\";\n\nexport interface ApiNotification {\n  id: string;\n  type: NotificationType;\n  message: string;\n  statusCode?: number;\n  timestamp: string;\n}\n\nexport const NOTIFICATION_EVENT = \"api:notification\" as const;\n\n// Suppresses duplicate toasts when the same error fires multiple times in quick succession.\nconst DEDUPE_WINDOW_MS = 2500;\nconst recentNotifications = new Map<string, ReturnType<typeof setTimeout>>();\n\n/**\n * Pushes an error or status notification outside of React (e.g. from API service files).\n * Identical notifications within 2.5 s are suppressed to prevent duplicate toasts.\n *\n * @example\n * pushNotification({ type: \"error\", message: \"Failed to load profile\", statusCode: 500 });\n */\nexport const pushNotification = (\n  notification: Omit<ApiNotification, \"id\" | \"timestamp\">,\n) => {\n  if (typeof window === \"undefined\") return;\n\n  const dedupeKey = `${notification.type}:${notification.statusCode ?? \"\"}:${notification.message}`;\n\n  if (recentNotifications.has(dedupeKey)) return;\n\n  // Auto-expire the key so the same error can reappear after the window closes.\n  const timer = setTimeout(() => recentNotifications.delete(dedupeKey), DEDUPE_WINDOW_MS);\n  recentNotifications.set(dedupeKey, timer);\n\n  window.dispatchEvent(\n    new CustomEvent(NOTIFICATION_EVENT, {\n      detail: {\n        ...notification,\n        id: crypto.randomUUID(),\n        timestamp: new Date().toISOString(),\n      },\n    }),\n  );\n};\n\nexport interface NotificationContextValue {\n  notifications: ApiNotification[];\n  dismiss: (id: string) => void;\n  dismissAll: () => void;\n  pushNotification: (\n    notification: Omit<ApiNotification, \"id\" | \"timestamp\">,\n  ) => void;\n}\n\nexport const NotificationContext = createContext<NotificationContextValue | null>(\n  null,\n);\n";

export const NOTIFICATION_PROVIDER_CONTENT =
  "// @internal — No changes needed\nimport {\n  type ReactNode,\n  useCallback,\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from \"react\";\nimport {\n  type ApiNotification,\n  NOTIFICATION_EVENT,\n  pushNotification,\n  NotificationContext,\n  type NotificationContextValue,\n} from \"../hooks/notification\";\n\nexport interface UseNotificationOptions {\n  maxNotifications?: number;\n  autoDismissMs?: number | false;\n}\n\nconst DEFAULT_MAX = 10;\nconst DEFAULT_AUTO_DISMISS_MS = 5000;\n\nexport const NotificationProvider = ({\n  children,\n  options,\n}: {\n  children: ReactNode;\n  options?: UseNotificationOptions;\n}) => {\n  const {\n    maxNotifications = DEFAULT_MAX,\n    autoDismissMs = DEFAULT_AUTO_DISMISS_MS,\n  } = options ?? {};\n\n  const [notifications, setNotifications] = useState<ApiNotification[]>([]);\n  const timersRef = useRef<Map<string, ReturnType<typeof setTimeout>>>(\n    new Map(),\n  );\n\n  const dismiss = useCallback((id: string) => {\n    setNotifications((prev) => prev.filter((n) => n.id !== id));\n    const timer = timersRef.current.get(id);\n    if (timer) {\n      clearTimeout(timer);\n      timersRef.current.delete(id);\n    }\n  }, []);\n\n  const dismissAll = useCallback(() => {\n    setNotifications([]);\n    timersRef.current.forEach((timer) => clearTimeout(timer));\n    timersRef.current.clear();\n  }, []);\n\n  useEffect(() => {\n    if (typeof window === \"undefined\") return;\n\n    // Captured for safe cleanup in React Strict Mode\n    const timers = timersRef.current;\n\n    const handleNotification = (event: Event) => {\n      const notification = (event as CustomEvent<ApiNotification>).detail;\n      if (!notification?.id) return;\n\n      setNotifications((prev) => {\n        if (prev.some((n) => n.id === notification.id)) {\n          return prev;\n        }\n\n        // Drop duplicates already on screen (guards against same-render-batch bursts).\n        if (prev.some((n) => n.message === notification.message && n.type === notification.type)) {\n          return prev;\n        }\n\n        const next = [...prev, notification];\n\n        if (next.length <= maxNotifications) {\n          return next;\n        }\n\n        // Remove timers for notifications that are being evicted\n        const removed = next.slice(0, next.length - maxNotifications);\n\n        // Defer timer cleanup to keep the state updater pure.\n        queueMicrotask(() => {\n          removed.forEach(({ id }) => {\n            const timer = timers.get(id);\n            if (timer) {\n              clearTimeout(timer);\n              timers.delete(id);\n            }\n          });\n        });\n\n        return next.slice(next.length - maxNotifications);\n      });\n\n      if (autoDismissMs !== false) {\n        const timer = setTimeout(() => {\n          dismiss(notification.id);\n        }, autoDismissMs);\n\n        timers.set(notification.id, timer);\n      }\n    };\n\n    window.addEventListener(NOTIFICATION_EVENT, handleNotification);\n\n    return () => {\n      window.removeEventListener(NOTIFICATION_EVENT, handleNotification);\n      timers.forEach((timer) => clearTimeout(timer));\n      timers.clear();\n    };\n  }, [maxNotifications, autoDismissMs, dismiss]);\n\n  const contextValue = useMemo<NotificationContextValue>(\n    () => ({\n      notifications,\n      dismiss,\n      dismissAll,\n      pushNotification,\n    }),\n    [notifications, dismiss, dismissAll],\n  );\n\n  return (\n    <NotificationContext.Provider value={contextValue}>\n      {children}\n    </NotificationContext.Provider>\n  );\n};\n";

export const USE_NOTIFICATION_HOOK_CONTENT =
  "import { useContext } from \"react\";\nimport { NotificationContext } from \"./notification\";\n\n/**\n * Hook to consume the centralized notification state.\n * Must be used within a <NotificationProvider>.\n */\nexport const useNotification = () => {\n  const context = useContext(NotificationContext);\n  if (!context) {\n    throw new Error(\n      \"useNotification must be used within a NotificationProvider\",\n    );\n  }\n  return context;\n};\n";

export const BASE_API_CLIENT_CONTENT =
  "// @internal — No changes needed\r\n/* eslint-disable @typescript-eslint/no-explicit-any */\r\nimport axios, {\r\n  AxiosError,\r\n  type AxiosInstance,\r\n  type AxiosRequestConfig,\r\n  type InternalAxiosRequestConfig,\r\n} from \"axios\";\r\n\r\nimport type { ApiError, TokenProvider } from \"./auth-methods/types\";\r\nimport { apiConfig } from \"./api.config\";\r\nimport { proxyTokenProvider } from \"./auth-methods/manager\";\r\nimport { pushNotification } from \"./hooks/notification\";\r\n\r\nconst API_TIMEOUT = 30000;\r\nconst REFRESH_TIMEOUT = 10000;\r\n\r\n// Helper to extract a human-readable string from various error response formats\r\nconst formatErrorMessage = (data: unknown): string | undefined => {\r\n  if (!data) return undefined;\r\n\r\n  if (typeof data.error === \"string\") return data.error;\r\n  if (typeof data.message === \"string\") return data.message;\r\n  if (typeof data.msg === \"string\") return data.msg;\r\n\r\n  if (data.detail !== undefined && data.detail !== null) {\r\n    if (typeof data.detail === \"string\") return data.detail;\r\n\r\n    if (Array.isArray(data.detail)) {\r\n      return data.detail\r\n        .map((err: unknown) => {\r\n          const field =\r\n            Array.isArray(err.loc) && err.loc.length\r\n              ? err.loc[err.loc.length - 1]\r\n              : undefined;\r\n\r\n          const msg = err.msg || \"Invalid value\";\r\n          return field ? `${field}: ${msg}` : msg;\r\n        })\r\n        .join(\"; \");\r\n    }\r\n\r\n    if (typeof data.detail === \"object\") {\r\n      return data.detail.message || data.detail.msg || \"Invalid request\";\r\n    }\r\n  }\r\n\r\n  return undefined;\r\n};\r\n\r\nconst DEFAULT_CONFIG: AxiosRequestConfig = {\r\n  baseURL: apiConfig.baseURL,\r\n  timeout: API_TIMEOUT,\r\n  headers: { \"Content-Type\": \"application/json\" },\r\n};\r\n\r\n/** Creates an Axios client with auto token injection and 401 refresh/retry */\r\nexport const createApiClient = (\r\n  tokenProvider?: TokenProvider,\r\n): AxiosInstance => {\r\n  const client = axios.create(DEFAULT_CONFIG);\r\n\r\n  let isRefreshing = false;\r\n  let failedQueue: Array<{\r\n    resolve: (token: string | null) => void;\r\n    reject: (error: unknown) => void;\r\n  }> = [];\r\n\r\n  const processQueue = (error: unknown, token: string | null = null) => {\r\n    failedQueue.forEach((prom) => {\r\n      if (error) {\r\n        prom.reject(error);\r\n      } else {\r\n        prom.resolve(token);\r\n      }\r\n    });\r\n    failedQueue = [];\r\n  };\r\n\r\n  // Request interceptor: inject token + custom headers\r\n  client.interceptors.request.use(\r\n    async (config: InternalAxiosRequestConfig) => {\r\n      config.baseURL = apiConfig.baseURL;\r\n\r\n      if (config.data instanceof FormData && config.headers) {\r\n        delete config.headers[\"Content-Type\"];\r\n      }\r\n\r\n      if (tokenProvider) {\r\n        const token = await tokenProvider.getToken();\r\n        if (token && token !== \"cookie-active\" && config.headers) {\r\n          config.headers.Authorization = `Bearer ${token}`;\r\n        }\r\n\r\n        const customHeaders = await tokenProvider.getCustomHeaders?.();\r\n        if (customHeaders && config.headers) {\r\n          Object.entries(customHeaders).forEach(([key, value]) => {\r\n            if (typeof config.headers.set === \"function\") {\r\n              config.headers.set(key, value);\r\n            } else {\r\n              config.headers[key] = value;\r\n            }\r\n          });\r\n        }\r\n      }\r\n\r\n      if (apiConfig.enableApiLogging) {\r\n        console.log(\r\n          `[API Request] ${config.method?.toUpperCase()} ${config.url}`,\r\n          config.params || config.data,\r\n        );\r\n      }\r\n\r\n      return config;\r\n    },\r\n    (error) => Promise.reject(error),\r\n  );\r\n\r\n  // Response interceptor: unwrap data, handle 401 refresh, normalize errors\r\n  client.interceptors.response.use(\r\n    (response) => {\r\n      const rawData = response?.data;\r\n      const res = apiConfig.unwrapResponseData\r\n        ? (rawData?.data ?? rawData)\r\n        : rawData;\r\n\r\n      if (apiConfig.enableApiLogging) {\r\n        console.log(\r\n          `[API Success] ${response.config.method?.toUpperCase()} ${response.config.url}`,\r\n          res,\r\n        );\r\n      }\r\n\r\n      return res;\r\n    },\r\n    async (error: AxiosError) => {\r\n      const originalRequest = error.config as InternalAxiosRequestConfig & {\r\n        _retry?: boolean;\r\n      };\r\n\r\n      // Handle 401 with token refresh\r\n      if (\r\n        error.response?.status === 401 &&\r\n        !originalRequest._retry &&\r\n        tokenProvider?.refreshToken\r\n      ) {\r\n        if (isRefreshing) {\r\n          return new Promise<string | null>((resolve, reject) => {\r\n            const timeoutId = setTimeout(() => {\r\n              reject(\r\n                new Error(\"Token refresh timeout - request took too long\"),\r\n              );\r\n            }, REFRESH_TIMEOUT);\r\n\r\n            failedQueue.push({\r\n              resolve: (token) => {\r\n                clearTimeout(timeoutId);\r\n                resolve(token);\r\n              },\r\n              reject: (err) => {\r\n                clearTimeout(timeoutId);\r\n                reject(err);\r\n              },\r\n            });\r\n          })\r\n            .then((token) => {\r\n              if (token && originalRequest.headers) {\r\n                originalRequest.headers.Authorization = `Bearer ${token}`;\r\n              }\r\n              return client(originalRequest);\r\n            })\r\n            .catch((err) => Promise.reject(err));\r\n        }\r\n\r\n        originalRequest._retry = true;\r\n        isRefreshing = true;\r\n\r\n        try {\r\n          const newToken = await tokenProvider.refreshToken();\r\n\r\n          if (newToken && originalRequest.headers) {\r\n            originalRequest.headers.Authorization = `Bearer ${newToken}`;\r\n            processQueue(null, newToken);\r\n            return client(originalRequest);\r\n          }\r\n\r\n          throw new Error(\"Refresh failed to return a valid token\");\r\n        } catch (refreshError) {\r\n          processQueue(refreshError, null);\r\n\r\n          // Refresh failed — signal the app to log the user out and clear the session.\r\n          if (typeof window !== \"undefined\") {\r\n            window.dispatchEvent(new Event(\"auth:logout\"));\r\n          }\r\n\r\n          // Notify the user. To redirect instead of showing a toast, handle \"auth:logout\" in your auth guard.\r\n          pushNotification({\r\n            type: \"error\",\r\n            message:\r\n              formatErrorMessage((error as unknown).response?.data) ||\r\n              \"Authentication failed. Please log in again.\",\r\n            statusCode: 401,\r\n          });\r\n\r\n          // Return early so the generic error handler below does not also fire a notification.\r\n          return Promise.reject(refreshError);\r\n        } finally {\r\n          isRefreshing = false;\r\n        }\r\n      } else if (error.response?.status === 401) {\r\n        // No token refresh configured — log the user out immediately.\r\n        if (typeof window !== \"undefined\") {\r\n          window.dispatchEvent(new Event(\"auth:logout\"));\r\n        }\r\n\r\n        pushNotification({\r\n          type: \"error\",\r\n          message:\r\n            formatErrorMessage(error.response?.data) ||\r\n            \"Authentication failed. Please log in again.\",\r\n          statusCode: 401,\r\n        });\r\n\r\n        // Return early so the generic error handler below does not also fire a notification.\r\n        throw error;\r\n      }\r\n\r\n      // Normalize the raw Axios error into a consistent ApiError shape.\r\n      const responseData = error.response?.data as unknown;\r\n      const apiError: ApiError = {\r\n        message:\r\n          formatErrorMessage(responseData) ||\r\n          error.message ||\r\n          \"An unexpected error occurred\",\r\n        code: responseData?.error || responseData?.code,\r\n        statusCode: error.response?.status,\r\n        originalError: error,\r\n      };\r\n\r\n      if (originalRequest) {\r\n        const endpoint = `${originalRequest.method?.toUpperCase()} ${originalRequest.url}`;\r\n        console.log(`[API ERROR - ${endpoint}]`, {\r\n          message: apiError.message,\r\n          code: apiError.code,\r\n          statusCode: apiError.statusCode,\r\n        });\r\n      }\r\n\r\n      // Surface the error to the user. Customize the UI in AppNotification.tsx.\r\n      pushNotification({\r\n        type: \"error\",\r\n        message: apiError.message,\r\n        statusCode: apiError.statusCode,\r\n      });\r\n\r\n      throw apiError;\r\n    },\r\n  );\r\n\r\n  return client;\r\n};\r\n\r\n/**\r\n * The globally configured API client instance.\r\n * It dynamically uses the Active Strategy defined in the AuthProvider.\r\n */\r\nexport const apiClient = createApiClient(proxyTokenProvider);\r\n";

export const INDEX_HOOKS_CONTENT =
  'import { createApiClient } from "./core";\nimport { proxyTokenProvider } from "../auth-methods/manager";\n\n/**\n * The globally configured API client instance.\n * It dynamically uses the Active Strategy defined in the AuthProvider.\n */\nexport const apiClient = createApiClient(proxyTokenProvider);\n';

export const QUERY_CONFIG_CONTENT =
  "// @user-config — customize query defaults here\nimport { type QueryKey, type UseMutationOptions, type UseQueryOptions, type UseQueryResult, type DefaultError, useMutation, useQuery } from '@tanstack/react-query';\n\nexport const useApiMutation = <TData = unknown, TVariables = void, TError = DefaultError, TContext = unknown>(mutationFn: (variables: TVariables) => Promise<TData>, options?: Omit<UseMutationOptions<TData, TError, TVariables, TContext>, 'mutationFn'>) => { return useMutation<TData, TError, TVariables, TContext>({ mutationFn, ...options }); };\n\nexport const useApiQuery = <TQueryFnData = unknown, TError = DefaultError, TData = TQueryFnData, TQueryKey extends QueryKey = QueryKey>(queryKey: TQueryKey, queryFn: () => Promise<TQueryFnData>, options?: Omit<UseQueryOptions<TQueryFnData, TError, TData, TQueryKey>, 'queryKey' | 'queryFn'>): UseQueryResult<TData, TError> => { return useQuery<TQueryFnData, TError, TData, TQueryKey>({ queryKey, queryFn, refetchOnWindowFocus: false, retry: (failureCount: number, error: unknown) => { const status = error?.statusCode ?? error?.status ?? error?.response?.status; if (status === 401 || status === 403 || status === 404 || status === 422) { return false; } return failureCount < 1; }, ...options }); };";

export const USE_HEADERS_HOOK_CONTENT =
  "import { useCallback } from \"react\";\nimport { getActiveProvider } from \"../auth-methods/manager\";\n\n/**\n * Hook to manage custom API headers securely.\n */\nexport const useHeaders = () => {\n  const provider = getActiveProvider();\n\n  const getCustomHeaders = useCallback(\n    () => provider?.getCustomHeaders?.() ?? {},\n    [provider],\n  );\n\n  const setCustomHeaders = useCallback(\n    (headers: Record<string, string>) => {\n      provider?.setCustomHeaders?.(headers);\n    },\n    [provider],\n  );\n\n  const removeCustomHeader = useCallback(\n    (key: string) => {\n      provider?.removeCustomHeader?.(key);\n    },\n    [provider],\n  );\n\n  return { getCustomHeaders, setCustomHeaders, removeCustomHeader };\n};\n";

export const NEXT_AUTH_PROVIDER_CONTENT =
  "// @internal — No changes needed\r\nimport { type TokenProvider } from \"../types\";\r\nimport { getSession } from \"next-auth/react\";\r\n\r\n// Extend the Session type to include accessToken\r\ndeclare module \"next-auth\" {\r\n    interface Session {\r\n        accessToken?: string;\r\n    }\r\n}\r\nlet customHeaders: Record<string, string> | null = null;\r\n\r\n// TokenProvider for NextAuth.js - retrieves token from session\r\ninterface NextAuthTokenProvider extends TokenProvider {\r\n    setTokens?: (tokens: { accessToken: string; refreshToken?: string }) => void;\r\n    setSession?: (\r\n        tokens?: { accessToken?: string; refreshToken?: string },\r\n        headers?: Record<string, string>,\r\n    ) => void;\r\n    clearTokens: () => void;\r\n    setCustomHeaders: (headers: Record<string, string>) => void;\r\n    getCustomHeaders: () => Record<string, string>;\r\n}\r\n\r\nexport const nextAuthTokenProvider: NextAuthTokenProvider = {\r\n    getToken: async () => {\r\n        const session = await getSession();\r\n        return (session?.accessToken as string) || null;\r\n    },\r\n\r\n    getCustomHeaders: () => {\r\n        if (customHeaders) return customHeaders;\r\n        if (typeof window !== \"undefined\") {\r\n            const stored = localStorage.getItem(\"reex_custom_headers\");\r\n            if (stored) {\r\n                try {\r\n                    return JSON.parse(stored);\r\n                } catch {\r\n                    return {};\r\n                }\r\n            }\r\n        }\r\n        return {};\r\n    },\r\n\r\n    setCustomHeaders: (headers) => {\r\n        customHeaders = headers;\r\n        if (typeof window !== \"undefined\") {\r\n            localStorage.setItem(\"reex_custom_headers\", JSON.stringify(headers));\r\n        }\r\n    },\r\n\r\n    refreshToken: undefined,\r\n\r\n    // Placeholder methods for compatibility with other providers\r\n    // NextAuth manages these internally via session\r\n    setTokens: () => {\r\n        if (process.env.NODE_ENV === \"development\") {\r\n            console.warn(\r\n                \"[NextAuthTokenProvider] setTokens is a no-op. NextAuth manages tokens via session.\",\r\n            );\r\n        }\r\n    },\r\n    setSession: (_tokens, headers) => {\r\n        if (headers) {\r\n            nextAuthTokenProvider.setCustomHeaders(headers);\r\n        }\r\n    },\r\n    clearTokens: () => {\r\n        customHeaders = null;\r\n        if (typeof window !== \"undefined\") {\r\n            localStorage.removeItem(\"reex_custom_headers\");\r\n        }\r\n        if (process.env.NODE_ENV === \"development\") {\r\n            console.warn(\r\n                \"[NextAuthTokenProvider] clearTokens token part is a no-op. Use signOut() from next-auth/react instead.\",\r\n            );\r\n        }\r\n    },\r\n};\r\n";

export const NEXT_AUTH_GUARD_CONTENT =
  "// @internal — No changes needed\r\n\"use client\";\r\n\r\nimport { SessionProvider } from \"next-auth/react\";\r\nimport { useEffect } from \"react\";\r\n\r\n/**\r\n * Authentication guard wrapper for NextAuth.js\r\n */\r\n\r\nexport const NextAuthGuard = ({ children }: { children: React.ReactNode }) => {\r\n  return (\r\n    <SessionProvider>\r\n      <NextAuthGuardInner>{children}</NextAuthGuardInner>\r\n    </SessionProvider>\r\n  );\r\n};\r\n\r\nconst NextAuthGuardInner = ({ children }: { children: React.ReactNode }) => {\r\n  // Listen for auth:logout events dispatched by core.ts when token refresh fails\r\n  useEffect(() => {\r\n    const handleLogout = () => {\r\n      import(\"next-auth/react\").then(({ signOut }) => signOut());\r\n    };\r\n\r\n    window.addEventListener(\"auth:logout\", handleLogout);\r\n    return () => window.removeEventListener(\"auth:logout\", handleLogout);\r\n  }, []);\r\n\r\n  return <>{children}</>;\r\n};\r\n";
